"""Alert data representations supporting multiple alerts per event."""

import uuid
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional
from level_crossing.common.types import AlertType, AlertStatus, SeverityLevel


@dataclass
class AlertRecord:
    """Auditable record of an alert generated by the system."""
    alert_id: str
    event_id: str
    alert_type: AlertType
    severity: SeverityLevel
    timestamp: float          # Pipeline active clock (sec)
    wall_clock_time: str      # UTC ISO 8601 string
    status: AlertStatus
    message: str
    snapshot_path: Optional[str] = None

    @classmethod
    def create(
        cls,
        event_id: str,
        alert_type: AlertType,
        severity: SeverityLevel,
        timestamp: float,
        message: str,
        snapshot_path: Optional[str] = None,
    ) -> "AlertRecord":
        return cls(
            alert_id=f"ALT-{uuid.uuid4().hex[:8].upper()}",
            event_id=event_id,
            alert_type=alert_type,
            severity=severity,
            timestamp=timestamp,
            wall_clock_time=datetime.now(timezone.utc).isoformat(),
            status=AlertStatus.GENERATED,
            message=message,
            snapshot_path=snapshot_path,
        )
